def priority(SH: float, EMP: float, AVG: float, CUR: float, RI: float, DIFF: float) -> float:
    """Score one candidate stack for the container being relocated. Lowest score wins."""
    if SH + 1 == 0:
        priority = 0
    else:
        urgency = (CUR - AVG) / (CUR + 1)
        # Promote stacks with more free space and fewer existing containers
        # and penalize stacks with higher average IDs and more potential blocking
        priority = (SH + 1 - EMP) * 0.3 + (AVG / (CUR + 1)) * 0.5 - (RI / (SH + 1)) * 0.2
    return priority
